func resetCredentialEnv(t *testing.T) (home, configPath string) {
	t.Helper()
	home = t.TempDir()
	t.Setenv("HOME", home)
	for _, name := range []string{
		"RESOURCEGURU_CONFIG",
		"RESOURCEGURU_CONFIG_DIR",
		"RESOURCEGURU_DATA_DIR",
		"RESOURCEGURU_STATE_DIR",
		"RESOURCEGURU_CACHE_DIR",
		"RESOURCEGURU_HOME",
		"XDG_CONFIG_HOME",
		"XDG_DATA_HOME",
		"XDG_STATE_HOME",
		"XDG_CACHE_HOME",
		"RESOURCEGURU_EMAIL",
		"RESOURCEGURU_PASSWORD",
	} {
		t.Setenv(name, "")
	}
	if restore, err := cliutil.SetHomeOverride(""); err == nil {
		t.Cleanup(restore)
	} else {
		t.Fatalf("reset home override: %v", err)
	}
	return home, filepath.Join(home, ".config", "resourceguru-cli", "config.toml")
}

func TestCredentialsFileWinsWhenLegacyConfigAlsoHasSecrets(t *testing.T) {
	_, configPath := resetCredentialEnv(t)
	if err := os.MkdirAll(filepath.Dir(configPath), 0o700); err != nil {
		t.Fatalf("mkdir config: %v", err)
	}
	if err := os.WriteFile(configPath, []byte("base_url = \"https://legacy.example\"\n"+legacyCredentialPairTOML("legacy-secret")), 0o600); err != nil {
		t.Fatalf("write legacy config: %v", err)
	}
	if err := cliutil.SaveCredentials(testCredentialPair("data-secret")); err != nil {
		t.Fatalf("SaveCredentials() error = %v", err)
	}

	cfg, err := config.Load("")
	if err != nil {
		t.Fatalf("Load() error = %v", err)
	}
	assertConfigCredential(t, cfg, "data-secret")
	assertAuthHeaderCarries(t, cfg, "data-secret", "legacy-secret")
}

